<template>
  <div>
    <div>
      <input class="inputBlock" v-model="inputText">
    </div>
    <hr>
    <div class="textBlock">
      <span v-for="(item, index) in inputText.split('')" :key=index
            :style="{color: index > readIndex ? 'black' : 'blue'}">{{ item }}</span>
    </div>
    <hr>
    <button @click="startTTS">开始说话</button>
    <hr>
    <div>{{ prompt }}</div>
    <div class="textBlock">
      {{ text }}
    </div>
    <hr>
    <button @click="startRecognize">开始说话</button>
  </div>
</template>

<script>
export default {
  name: 'HelloWorld',
  data() {
    return {
      inputText: '哈哈',
      utterance: '',
      readIndex: -1,
      speechRecognition: "",
      recognition: "",
      text: "",
      prompt: ""
    };
  },
  mounted() {
    try {
      // this.speechRecognition = window.SpeechRecognition;
      this.recognition = new window.webkitSpeechRecognition();
    } catch (err) {
      // this.speechRecognition = window.webkitSpeechRecognition;
      this.recognition = new window.SpeechRecognition();
    }
    // this.recognition = new this.speechRecognition();
    console.log(this.recognition)

    this.recognition.lang = 'zh-CN';
    this.recognition.interimResults = false;
    this.recognition.maxAlternatives = 1;
    let _this = this
    this.recognition.onresult = function (event) {
      console.log("11", event)
      _this.prompt = event.results[0][0].transcript;
    }

    this.recognition.onaudiostart = function (event) {
      console.log(event)
      _this.prompt = '音频开始';
    }

    this.recognition.onaudioend = function (event) {
      console.log(event)
      _this.prompt = '音频结束';
    }

    this.recognition.onsoundstart = function (event) {
      console.log(event)
      _this.prompt = '声音开始';
    }

    this.recognition.onsoundend = function (event) {
      console.log(event)
      _this.prompt = '声音结束';
    }

    this.recognition.onend = function (event) {
      console.log(event)
      _this.prompt = '识别结束';
    }

  },
  methods: {
    startTTS() {
      let _this = this;
      const synth = window.speechSynthesis;
      this.utterance = new SpeechSynthesisUtterance(this.inputText);

      this.utterance.onend = function () {
        console.log("Speech ended");
        _this.readIndex = -1;
      };

      this.utterance.boundary = 'word';

      this.utterance.onboundary = function (event) {
        console.log(`到达边界: ${event.name}, 字符位置: ${event.charIndex}`);
        _this.readIndex = event.charIndex;
        console.log("=====", _this.readIndex)
      }
      synth.speak(this.utterance)

    },
    startRecognize() {
      this.recognition.start();
      this.prompt = '识别中'
    }
  }
}
</script>

